  function membersV2(){let q='',tag='All';const draw=()=>{const tags=[...new Set(S().members.flatMap(x=>x.tags||[]))],data=S().members.filter(x=>(!q||U().norm(name(x)+' '+x.memberNumber+' '+x.email+' '+x.phone).includes(U().norm(q)))&&(tag==='All'||(x.tags||[]).includes(tag)));Gym.app.innerHTML=head('Members','Advanced profiles, tags, notes, billing and visit history.')+`<section class="panel"><div class="toolbar"><div class="field search"><label>Search</label><input id="memberSearch" value="${esc(q)}" placeholder="Name, member number, email or phone"></div><div class="field"><label>Tag</label><select id="tagFilter"><option>All</option>${tags.map(x=>`<option ${x===tag?'selected':''}>${esc(x)}</option>`).join('')}</select></div><span class="badge">${data.length} results</span></div>${table(['Member','Contact','Tags','Membership','Visits','Action'],data.map(m=>`<tr><td><strong>${esc(name(m))}</strong><br><small>${m.memberNumber}</small></td><td>${esc(m.email)}<br><small>${esc(m.phone)}</small></td><td>${(m.tags||[]).map(x=>`<span class="tag">${esc(x)}</span>`).join('')||'—'}</td><td>${badge(Gym.Calc.validMembership(m.id)?'Active':'Inactive')}</td><td>${S().visits.filter(x=>x.memberId===m.id).length}</td><td><button class="btn btn-sm" data-profile="${m.id}">View Profile</button></td></tr>`))}</section>`;document.querySelector('#memberSearch').oninput=e=>{q=e.target.value;draw()};document.querySelector('#tagFilter').onchange=e=>{tag=e.target.value;draw()};document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>memberProfile(S().members.find(x=>x.id===b.dataset.profile)))};draw()}
  function csv(rows,filename){const text=rows.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n'),blob=new Blob([text],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();URL.revokeObjectURL(a.href)}
  function reportsV2(){let type='invoices';const data=()=>type==='invoices'?[['Invoice','Member','Due','Total','Outstanding','Status'],...S().invoices.map(x=>{const t=Gym.Finance.invoiceTotals(x);return[x.invoiceNumber,member(x.memberId),x.dueDate,x.total,t.outstandingAmount,t.status]})]:type==='visits'?[['Member','Check-In','Check-Out','Duration Minutes'],...S().visits.map(x=>[member(x.memberId),x.checkInTime,x.checkOutTime,x.durationMinutes])]:type==='equipment'?[['Equipment','Category','Room','Status','Purchase Cost'],...S().equipment.map(x=>[x.name,x.category,room(x.roomId),x.status,x.purchaseCost])]:[['Equipment','Type','Scheduled','Completed','Cost','Status'],...S().maintenanceRecords.map(x=>[equipment(x.equipmentId),x.type,x.scheduledDate,x.completedDate,x.cost,x.status])];const draw=()=>{const rows=data();Gym.app.innerHTML=head('Reports','V2 operational reports with genuine local CSV export.',`<button class="btn" id="exportCSV">Export Displayed CSV</button>`)+`<section class="panel"><div class="toolbar"><div class="field"><label>Report</label><select id="v2Report"><option value="invoices" ${type==='invoices'?'selected':''}>Invoice Report</option><option value="visits" ${type==='visits'?'selected':''}>Visit Duration Report</option><option value="equipment" ${type==='equipment'?'selected':''}>Equipment Report</option><option value="maintenance" ${type==='maintenance'?'selected':''}>Maintenance Report</option></select></div><span class="badge">${rows.length-1} records</span></div>${table(rows[0],rows.slice(1).map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`))}</section>`;document.querySelector('#v2Report').onchange=e=>{type=e.target.value;draw()};document.querySelector('#exportCSV').onclick=()=>csv(data(),`gym-${type}-report-${U().today()}.csv`)};draw()}
  function settingsV2(){const s=S().settings;Gym.app.innerHTML=head('Settings','Configure V2 behavior, backups and data reliability tools.')+`<div class="grid-2"><section class="panel"><h2>General & Interface</h2><form id="v2Settings" class="form-grid">${field('Gym name','gymName','text',s.gymName)}${field('Currency','currency','select',s.currency,['USD','EUR','GBP','TRY','CAD','AUD'])}${field('Theme','theme','select',s.theme,['light','dark'])}${field('Compact mode','compactMode','select',String(s.compactMode),[{value:'false',label:'Off'},{value:'true',label:'On'}])}${field('Default page size','defaultPageSize','select',String(s.defaultPageSize),['10','25','50'])}${field('Check-in protection (minutes)','duplicateCheckInMinutes','number',s.duplicateCheckInMinutes)}${field('Cancellation notice (hours)','minimumCancellationHours','number',s.minimumCancellationHours)}${field('Default class duration','defaultClassDuration','number',s.defaultClassDuration)}${field('Default tax rate (%)','defaultTaxRate','number',s.defaultTaxRate)}${field('Expiration warning days','expirationWarningDays','text',(s.expirationWarningDays||[]).join(', '))}<div class="wide"><button class="btn btn-primary">Save Settings</button></div></form></section><section class="panel"><h2>Data Management</h2><p>V2 backups include all entities, settings and metadata. Merge uses incoming records for matching IDs.</p><div class="quick-actions"><button class="btn" id="v2Export">Export V2 Backup</button><label class="btn" for="v2Import">Import Backup</label><input id="v2Import" type="file" accept="application/json" hidden><select id="v2Mode" style="width:auto"><option value="merge">Merge</option><option value="replace">Replace</option></select></div><h3 style="margin-top:24px">Data Integrity</h3><button class="btn" id="integrity">Run Data Integrity Check</button><div id="integrityResult" style="margin-top:12px"></div><h3 style="margin-top:24px">Strong Reset</h3><button class="btn btn-danger" id="resetV2">Choose Reset Option</button></section></div>`;document.querySelector('#v2Settings').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));Object.assign(s,v,{compactMode:v.compactMode==='true',defaultPageSize:Number(v.defaultPageSize),duplicateCheckInMinutes:Number(v.duplicateCheckInMinutes),minimumCancellationHours:Number(v.minimumCancellationHours),defaultClassDuration:Number(v.defaultClassDuration),defaultTaxRate:Number(v.defaultTaxRate),expirationWarningDays:v.expirationWarningDays.split(',').map(Number).filter(Number.isFinite)});Gym.save();location.reload()};document.querySelector('#integrity').onclick=()=>{const r=Gym.Integrity.check(S());document.querySelector('#integrityResult').innerHTML=r.valid?`<div class="badge badge-active">Passed · ${r.checkedAt}</div>`:`<div class="error">${r.errors.map(esc).join('<br>')}</div>`};document.querySelector('#v2Export').onclick=()=>{const blob=new Blob([Gym.Storage.export()],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`gym-management-v2-backup-${U().today()}.json`;a.click();URL.revokeObjectURL(a.href)};document.querySelector('#v2Import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const parsed=JSON.parse(await file.text()),incoming=parsed.applicationState;if(parsed.schemaVersion!==2||!incoming)throw new Error('Unsupported backup schema.');const result=Gym.Integrity.check(incoming);if(!result.valid)throw new Error(result.errors[0]);const apply=()=>{if(document.querySelector('#v2Mode').value==='replace')Gym.state=JSON.parse(JSON.stringify(incoming));else for(const c of Gym.Integrity.collections){const map=new Map((S()[c]||[]).map(x=>[x.id,x]));(incoming[c]||[]).forEach(x=>map.set(x.id,x));S()[c]=[...map.values()]}Gym.log('Import Performed','system','import','A validated V2 backup was imported.');Gym.save();location.reload()};if(document.querySelector('#v2Mode').value==='replace')Gym.UI.confirm('Replace all current data with this validated backup?',apply);else apply()}catch(error){Gym.UI.toast(`Import rejected: ${error.message}`,'error')}};document.querySelector('#resetV2').onclick=()=>Gym.UI.modal('Reset All Data',`<p>This action replaces every current record.</p><form>${field('Reset choice','choice','select','demo',[{value:'demo',label:'Reset and Restore Demo Data'},{value:'empty',label:'Reset to Empty State'}])}${field('Type RESET to confirm','confirmation','text','')}</form>`,(b,close)=>{const v=formData(b);if(v.confirmation!=='RESET')return Gym.UI.toast('Type RESET exactly to continue.','error');const base=Gym.Migrations.toV2(Gym.createDemo());Gym.state=v.choice==='demo'?Gym.enhanceDemoV2(base):Object.assign(base,Object.fromEntries(Gym.Integrity.collections.map(c=>[c,[]])));Gym.save();close();location.reload()},'Reset All Data')}
  function memberEditor(item={}){Gym.UI.modal(item.id?'Edit Member':'Add Member',`<form class="form-grid">${field('First name','firstName','text',item.firstName)}${field('Last name','lastName','text',item.lastName)}${field('Email','email','email',item.email)}${field('Phone','phone','tel',item.phone)}${field('Join date','joinDate','date',item.joinDate||U().today())}${field('Status','status','select',item.status||'Active',['Active','Suspended','Inactive'])}${field('Tags (comma separated)','tags','text',(item.tags||[]).join(', '))}${field('Address','address','text',item.address)}${field('Emergency contact','emergencyContactName','text',item.emergencyContactName)}${field('Emergency phone','emergencyContactPhone','tel',item.emergencyContactPhone)}<div class="wide">${field('Profile notes','notes','textarea',item.notes)}</div></form>`,(b,close)=>{const v=formData(b);if(!v.firstName.trim()||!v.lastName.trim()||!/^\S+@\S+\.\S+$/.test(v.email))return Gym.UI.toast('First name, last name and a valid email are required.','error');v.tags=v.tags.split(',').map(x=>x.trim()).filter(Boolean);const duplicate=S().members.find(x=>x.id!==item.id&&x.email.toLowerCase()===v.email.toLowerCase());if(duplicate)return Gym.UI.toast('Another member already uses this email.','error');const now=new Date().toISOString(),record={...item,...v,id:item.id||U().id('mem'),memberNumber:item.memberNumber||`GM-${String(1001+S().members.length).padStart(4,'0')}`,createdAt:item.createdAt||now,updatedAt:now};S().members=item.id?S().members.map(x=>x.id===item.id?record:x):[...S().members,record];Gym.log(item.id?'Member Updated':'Member Created','member',record.id,`${name(record)} was ${item.id?'updated':'created'}.`);Gym.save();close();Gym.render();Gym.UI.toast(`Member ${item.id?'updated':'created'}.`,'success')})}
  function membersComplete(){let q='',status='All',tag='All',selected=new Set();const readFilters=()=>{const saved=S().savedFilters.filter(x=>x.page==='members');return saved};const draw=()=>{const tags=[...new Set(S().members.flatMap(x=>x.tags||[]))],data=S().members.filter(x=>(!q||U().norm(name(x)+' '+x.memberNumber+' '+x.email+' '+x.phone).includes(U().norm(q)))&&(status==='All'||x.status===status)&&(tag==='All'||(x.tags||[]).includes(tag)));Gym.app.innerHTML=head('Members','Complete member CRUD, profiles, tags, notes, filters and safe bulk status actions.',`<button class="btn btn-primary" id="addMember">Add Member</button>`)+`<section class="panel"><div class="toolbar"><div class="field search"><label>Search</label><input id="memberSearch" value="${esc(q)}" placeholder="Name, number, email or phone"></div><div class="field"><label>Status</label><select id="memberStatus"><option>All</option>${['Active','Suspended','Inactive'].map(x=>`<option ${x===status?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Tag</label><select id="tagFilter"><option>All</option>${tags.map(x=>`<option ${x===tag?'selected':''}>${esc(x)}</option>`).join('')}</select></div><button class="btn" id="clearFilters">Clear Filters</button><button class="btn" id="saveFilter">Save Filter</button><select id="savedFilter" style="width:auto"><option value="">Saved Filters</option>${readFilters().map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><span class="badge">${data.length} results · ${(q?1:0)+(status!=='All'?1:0)+(tag!=='All'?1:0)} active filters</span></div><div class="toolbar"><button class="btn" data-bulk="Active">Activate Selected</button><button class="btn" data-bulk="Suspended">Suspend Selected</button><span class="muted">${selected.size} selected</span></div>${table(['Select','Member','Contact','Tags','Status','Membership','Actions'],data.map(m=>`<tr><td><input type="checkbox" aria-label="Select ${esc(name(m))}" data-select="${m.id}" ${selected.has(m.id)?'checked':''}></td><td><strong>${esc(name(m))}</strong><br><small>${m.memberNumber}</small></td><td>${esc(m.email)}<br><small>${esc(m.phone)}</small></td><td>${(m.tags||[]).map(x=>`<span class="tag">${esc(x)}</span>`).join('')||'—'}</td><td>${badge(m.status)}</td><td>${badge(Gym.Calc.validMembership(m.id)?'Active':'Inactive')}</td><td class="actions"><button class="btn btn-sm" data-profile="${m.id}">Profile</button><button class="btn btn-sm" data-edit-member="${m.id}">Edit</button><button class="btn btn-sm" data-delete-member="${m.id}">Delete</button></td></tr>`))}</section>`;document.querySelector('#addMember').onclick=()=>memberEditor();document.querySelector('#memberSearch').oninput=e=>{q=e.target.value;draw()};document.querySelector('#memberStatus').onchange=e=>{status=e.target.value;draw()};document.querySelector('#tagFilter').onchange=e=>{tag=e.target.value;draw()};document.querySelector('#clearFilters').onclick=()=>{q='';status='All';tag='All';draw()};document.querySelector('#saveFilter').onclick=()=>Gym.UI.modal('Save Member Filter',`<form>${field('Filter name','name','text','')}</form>`,(b,close)=>{const filterName=formData(b).name.trim();if(!filterName)return Gym.UI.toast('Filter name is required.','error');S().savedFilters.push({id:U().id('filter'),page:'members',name:filterName,criteria:{q,status,tag},createdAt:new Date().toISOString()});Gym.save();close();draw();Gym.UI.toast('Filter saved.','success')});document.querySelector('#savedFilter').onchange=e=>{const f=S().savedFilters.find(x=>x.id===e.target.value);if(f){({q='',status='All',tag='All'}=f.criteria);draw()}};document.querySelectorAll('[data-select]').forEach(c=>c.onchange=()=>{c.checked?selected.add(c.dataset.select):selected.delete(c.dataset.select);draw()});document.querySelectorAll('[data-bulk]').forEach(b=>b.onclick=()=>{if(!selected.size)return Gym.UI.toast('Select at least one member.','warning');Gym.UI.confirm(`${b.dataset.bulk==='Active'?'Activate':'Suspend'} ${selected.size} selected members?`,()=>{S().members.forEach(m=>{if(selected.has(m.id)){m.status=b.dataset.bulk;m.updatedAt=new Date().toISOString()}});Gym.log('Bulk Member Status','member','bulk',`${selected.size} members changed to ${b.dataset.bulk}.`);selected.clear();Gym.save();draw();Gym.UI.toast('Bulk member update completed.','success')})});document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>memberProfile(S().members.find(x=>x.id===b.dataset.profile)));document.querySelectorAll('[data-edit-member]').forEach(b=>b.onclick=()=>memberEditor(S().members.find(x=>x.id===b.dataset.editMember)));document.querySelectorAll('[data-delete-member]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteMember,blocked=S().memberships.some(x=>x.memberId===id&&['Active','Frozen'].includes(Gym.Calc.membershipStatus(x)))||S().classBookings.some(x=>x.memberId===id&&x.status!=='Cancelled');if(blocked)return Gym.UI.toast('Deletion blocked by active membership or booking relationships.','error');Gym.UI.confirm('Delete this member permanently?',()=>{S().members=S().members.filter(x=>x.id!==id);Gym.save();draw()})})};draw()}
  function classEditor(item={}){Gym.UI.modal(item.id?'Edit Class':'Create Class',`<form class="form-grid">${field('Name','name','text',item.name)}${field('Type','type','select',item.type||'Yoga',['Yoga','Pilates','Spinning','HIIT','Boxing','Cross Training','Functional Training','Strength Training','Other'])}${field('Trainer','trainerId','select',item.trainerId||S().trainers[0]?.id,opts(S().trainers))}${field('Room','roomId','select',item.roomId||S().rooms[0]?.id,opts(S().rooms,x=>x.name))}${field('Date','date','date',item.date||U().today())}${field('Start','startTime','time',item.startTime||'18:00')}${field('End','endTime','time',item.endTime||'19:00')}${field('Capacity','capacity','number',item.capacity||10)}${field('Status','status','select',item.status||'Scheduled',['Scheduled','Ongoing','Completed','Cancelled'])}<div class="wide">${field('Description','description','textarea',item.description)}</div></form>`,(b,close)=>{const v=formData(b),roomRecord=S().rooms.find(x=>x.id===v.roomId);if(!v.name||v.startTime>=v.endTime||!roomRecord||roomRecord.status!=='Active'||Number(v.capacity)>Number(roomRecord.capacity))return Gym.UI.toast('Enter valid class details within active room capacity.','error');const conflict=S().classes.find(x=>x.id!==item.id&&x.date===v.date&&x.status!=='Cancelled'&&U().overlap(v.startTime,v.endTime,x.startTime,x.endTime)&&(x.trainerId===v.trainerId||x.roomId===v.roomId));if(conflict)return Gym.UI.toast(`Conflict with ${conflict.name} on ${date(conflict.date)}.`,'error');v.capacity=Number(v.capacity);saveRecord('classes',item,v,'cl','Class');close();Gym.render();Gym.UI.toast('Class saved.','success')})}
  function seriesEditor(){Gym.UI.modal('Create Recurring Class Series',`<form class="form-grid">${field('Name','name','text','')}${field('Type','type','select','Yoga',['Yoga','Pilates','Spinning','HIIT','Boxing','Cross Training','Functional Training','Strength Training','Other'])}${field('Trainer','trainerId','select',S().trainers[0]?.id,opts(S().trainers))}${field('Room','roomId','select',S().rooms[0]?.id,opts(S().rooms,x=>x.name))}${field('Start date','startDate','date',U().today())}${field('End date','endDate','date',U().addDays(U().today(),28))}${field('Weekdays','weekdays','text','Monday, Wednesday')}${field('Start time','startTime','time','18:00')}${field('End time','endTime','time','19:00')}${field('Capacity','capacity','number',10)}${field('Description','description','textarea','Recurring group class')}</form>`,(b,close)=>{const v=formData(b),days=v.weekdays.split(',').map(x=>x.trim().toLowerCase()),dayNames=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];if(!v.name||v.startDate>v.endDate||v.startTime>=v.endTime||!days.length)return Gym.UI.toast('Complete all series fields with valid dates and times.','error');const instances=[];for(let d=v.startDate;d<=v.endDate;d=U().addDays(d,1)){if(days.includes(dayNames[new Date(d+'T12:00:00').getDay()]))instances.push(d)}if(!instances.length)return Gym.UI.toast('The selected range contains none of those weekdays.','error');const conflicts=instances.map(d=>({date:d,match:S().classes.find(x=>x.date===d&&x.status!=='Cancelled'&&U().overlap(v.startTime,v.endTime,x.startTime,x.endTime)&&(x.trainerId===v.trainerId||x.roomId===v.roomId))})).filter(x=>x.match);if(conflicts.length)return Gym.UI.toast(`Series rejected. Conflicts: ${conflicts.map(x=>`${date(x.date)} (${x.match.name})`).join(', ')}`,'error');const roomRecord=S().rooms.find(x=>x.id===v.roomId);if(!roomRecord||roomRecord.status!=='Active'||Number(v.capacity)>Number(roomRecord.capacity))return Gym.UI.toast('Room is unavailable or capacity is too high.','error');const seriesId=U().id('series'),now=new Date().toISOString(),records=instances.map(d=>({id:U().id('cl'),seriesId,name:v.name,type:v.type,trainerId:v.trainerId,roomId:v.roomId,date:d,startTime:v.startTime,endTime:v.endTime,capacity:Number(v.capacity),status:'Scheduled',description:v.description,createdAt:now,updatedAt:now}));S().classes.push(...records);Gym.log('Class Series Created','classSeries',seriesId,`${records.length} ${v.name} class instances created.`);Gym.save();close();Gym.render();Gym.UI.toast(`${records.length} recurring classes created.`,'success')})}
  function classesComplete(){Gym.app.innerHTML=head('Classes','Single and recurring classes with atomic conflict validation.',`<div class="quick-actions"><button class="btn btn-primary" id="addClass">Create Class</button><button class="btn" id="addSeries">Create Recurring Series</button></div>`)+`<section class="panel">${table(['Class','Schedule','Trainer','Room','Capacity','Bookings','Status','Actions'],[...S().classes].sort((a,b)=>(a.date+a.startTime).localeCompare(b.date+b.startTime)).map(x=>{const counts=Gym.Calc.classCounts(x.id);return `<tr><td><strong>${esc(x.name)}</strong><br><small>${x.type}${x.seriesId?' · Recurring':''}</small></td><td>${date(x.date)}<br><small>${x.startTime}–${x.endTime}</small></td><td>${trainer(x.trainerId)}</td><td>${room(x.roomId)}</td><td>${x.capacity}</td><td>${counts.confirmed} confirmed · ${counts.waiting} waiting</td><td>${badge(x.status)}</td><td><button class="btn btn-sm" data-edit-class="${x.id}">Edit</button></td></tr>`}) )}</section>`;document.querySelector('#addClass').onclick=()=>classEditor();document.querySelector('#addSeries').onclick=seriesEditor;document.querySelectorAll('[data-edit-class]').forEach(b=>b.onclick=()=>classEditor(S().classes.find(x=>x.id===b.dataset.editClass)))}
  function attendanceComplete(){let classId=S().classes[0]?.id||'';const draw=()=>{const bookings=S().classBookings.filter(x=>x.classId===classId&&x.status==='Confirmed');Gym.app.innerHTML=head('Attendance','Bulk mark participants present, then adjust individual outcomes including Excused.')+`<section class="panel"><div class="toolbar"><div class="field"><label>Class</label><select id="attendanceClass">${opts(S().classes,x=>`${x.name} · ${date(x.date)}`).map(x=>`<option value="${x.value}" ${x.value===classId?'selected':''}>${esc(x.label)}</option>`).join('')}</select></div><button class="btn" id="allPresent">Mark All Present</button></div><form id="attendanceV2">${table(['Member','Attendance'],bookings.map(b=>`<tr><td>${member(b.memberId)}</td><td><select name="${b.id}">${['Pending','Present','Absent','No Show','Excused'].map(x=>`<option ${x===b.attendanceStatus?'selected':''}>${x}</option>`).join('')}</select></td></tr>`))}<button class="btn btn-primary" style="margin-top:14px">Save Attendance</button></form></section>`;document.querySelector('#attendanceClass').onchange=e=>{classId=e.target.value;draw()};document.querySelector('#allPresent').onclick=()=>document.querySelectorAll('#attendanceV2 select').forEach(x=>x.value='Present');document.querySelector('#attendanceV2').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),prepared=bookings.map(b=>({booking:b,status:fd.get(b.id)}));for(const {booking,status} of prepared){booking.attendanceStatus=status;const existing=S().attendanceRecords.find(x=>x.memberId===booking.memberId&&x.classId===booking.classId),record={id:existing?.id||U().id('att'),bookingId:booking.id,classId:booking.classId,memberId:booking.memberId,status,updatedAt:new Date().toISOString(),createdAt:existing?.createdAt||new Date().toISOString()};S().attendanceRecords=existing?S().attendanceRecords.map(x=>x.id===existing.id?record:x):[...S().attendanceRecords,record]}Gym.log('Attendance Saved','class',classId,`Attendance saved for ${prepared.length} participants.`);Gym.save();Gym.UI.toast('Attendance saved.','success')}};draw()}
  function notificationsComplete(){let selected=new Set();const draw=()=>{Gym.app.innerHTML=head('Notifications','Live operational alerts with safe individual and bulk actions.',`<button class="btn" id="markAll">Mark All Read</button>`)+`<section class="panel"><div class="toolbar"><button class="btn" id="selectedRead">Mark Selected Read</button><button class="btn btn-danger" id="selectedDelete">Delete Selected</button><span class="muted">${selected.size} selected</span></div><div class="notification-list">${S().notifications.length?S().notifications.map(x=>`<article class="notice ${x.read?'read':''}"><input type="checkbox" aria-label="Select ${esc(x.title)}" data-select-note="${x.id}" ${selected.has(x.id)?'checked':''}><div><span class="${U().statusClass(x.priority)}">${x.priority}</span><h3>${esc(x.title)}</h3><p>${esc(x.message)}</p><small class="muted">${U().datetime(x.createdAt)} · ${x.type}</small></div><div class="actions"><button class="btn btn-sm" data-read="${x.id}">${x.read?'Mark Unread':'Mark Read'}</button><button class="btn btn-sm" data-delete="${x.id}">Delete</button></div></article>`).join(''):Gym.UI.empty('No notifications')}</div></section>`;document.querySelector('#markAll').onclick=()=>{S().notifications.forEach(x=>x.read=true);Gym.save();draw()};document.querySelectorAll('[data-select-note]').forEach(c=>c.onchange=()=>{c.checked?selected.add(c.dataset.selectNote):selected.delete(c.dataset.selectNote);draw()});document.querySelector('#selectedRead').onclick=()=>{if(!selected.size)return Gym.UI.toast('Select notifications first.','warning');S().notifications.forEach(x=>{if(selected.has(x.id))x.read=true});selected.clear();Gym.save();draw()};document.querySelector('#selectedDelete').onclick=()=>{if(!selected.size)return Gym.UI.toast('Select notifications first.','warning');Gym.UI.confirm(`Delete ${selected.size} selected notifications?`,()=>{S().notifications=S().notifications.filter(x=>!selected.has(x.id));selected.clear();Gym.save();draw()})};document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{const x=S().notifications.find(n=>n.id===b.dataset.read);x.read=!x.read;Gym.save();draw()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>Gym.UI.confirm('Delete this notification?',()=>{S().notifications=S().notifications.filter(x=>x.id!==b.dataset.delete);Gym.save();draw()}))};draw()}
  Gym.V2Pages={dashboard:dashboardV2,members:membersComplete,classes:classesComplete,attendance:attendanceComplete,checkin:checkinV2,reports:reportsV2,settings:settingsV2,equipment:equipmentPage,maintenance:maintenancePage,staff:staffPage,'personal-training':personalTrainingPage,invoices:invoicesPage,notifications:notificationsComplete,activity:activityPage};
